<script setup lang="ts">
import { computed, ref, onUnmounted } from 'vue';
import { useDispatchStore } from '../stores/dispatch';
const store=useDispatchStore(),data=ref<any>(null),busy=ref(false),message=ref(''),error=ref(''),saved=ref('');
let epoch=0;onUnmounted(()=>{epoch++;});
const dirty=computed(()=>data.value&&saved.value!==JSON.stringify(data.value.saved));
const plcFields=[['deviceId','PLC编号','text'],['displayName','名称','text'],['ipAddress','IPv4地址','text'],['port','端口','number'],['siemensSeries','系列','text'],['signalCsvPath','后台点表CSV路径','text'],['pollIntervalMs','轮询周期ms','number'],['staleAfterMs','数据过期ms','number']];
const agvFields=[['vehicleId','车辆编号','text'],['displayName','名称','text'],['ipAddress','IPv4地址','text'],['port','状态端口','number'],['navigationPort','导航端口','number']];
async function run(fn:()=>Promise<any>){if(busy.value)return;const n=++epoch;busy.value=true;error.value='';try{const d=await fn();if(n!==epoch)return;data.value=d;saved.value=JSON.stringify(d.saved);message.value=d.restartRequired?'配置已保存，需受控重启后台后生效；当前运行配置尚未改变。':'已读取后台当前配置。';}catch(e){if(n===epoch)error.value=e instanceof Error?e.message:String(e);}finally{if(n===epoch)busy.value=false;}}
function load(){void run(()=>store.api('/api/communication'));}
function save(){if(!data.value)return;void run(()=>store.api('/api/communication',{expectedRevision:data.value.revision,configuration:data.value.saved}));}
</script>
<template><section class="management-page communication-page"><header class="management-title"><h2>PLC / AGV 通信配置</h2><RouterLink to="/engineering">返回工程配置中心</RouterLink></header><p>本页维护调度后台的实际连接配置，保留地图绑定及其他全局参数。保存不会启动设备；运行任务和地图切换期间仍由后台拒绝不允许的修改。</p><p v-if="store.engineeringSimulationOnly" class="inline-warning">工程隔离实例禁止读取或保存现场通信。请在工程配置中心编辑模拟连接参数。</p><div class="communication-actions"><button :disabled="busy||store.demoMode||store.engineeringSimulationOnly" @click="load">读取后台通信配置</button><button class="accent-button" :disabled="busy||!data?.canManage||!dirty||store.engineeringSimulationOnly" @click="save">保存连接配置</button><span>{{dirty?'存在未保存修改':''}}</span></div><p v-if="error" class="inline-warning" role="alert">{{error}} <RouterLink to="/tasks">查询原任务</RouterLink> · <RouterLink to="/maps">复核地图切换</RouterLink></p><p role="status">{{message}}</p>
<template v-if="data"><p>修订{{data.revision}} · {{data.restartRequired?'保存与运行配置不一致':'保存与运行配置一致'}}</p><fieldset :disabled="busy||!data.canManage"><legend>PLC连接</legend><article v-for="(p,i) in data.saved.plcs" :key="i"><label><input v-model="p.enabled" type="checkbox"/>后台启动时启用采集</label><div class="communication-grid"><label v-for="f in plcFields" :key="f[0]">{{f[1]}}<input v-model="p[f[0]!]" :type="f[2]" @change="f[2]==='number'&&(p[f[0]!]=Number(p[f[0]!]))"/></label></div><button @click="data.saved.plcs.splice(i,1)">移除此连接稿</button></article><button @click="data.saved.plcs.push({deviceId:'PLC-NEW',displayName:'新PLC',enabled:false,siemensSeries:'S1200',ipAddress:'',port:102,signalCsvPath:'',pollIntervalMs:500,connectTimeoutMs:3000,receiveTimeoutMs:3000,reconnectDelayMs:3000,staleAfterMs:5000,interruptedFailureThreshold:3,readBlockSizeBytes:200})">新增PLC连接</button></fieldset>
<fieldset :disabled="busy||!data.canManage"><legend>AGV连接</legend><label><input v-model="data.saved.agvEnabled" type="checkbox"/>后台AGV通信采集</label><article v-for="(v,i) in data.saved.agvs" :key="i"><label><input v-model="v.enabled" type="checkbox"/>启用此车辆</label><div class="communication-grid"><label v-for="f in agvFields" :key="f[0]">{{f[1]}}<input v-model="v[f[0]!]" :type="f[2]" @change="f[2]==='number'&&(v[f[0]!]=Number(v[f[0]!]))"/></label></div><button @click="data.saved.agvs.splice(i,1)">移除此车辆连接稿</button></article><button @click="data.saved.agvs.push({vehicleId:'AGV-NEW',displayName:'新车辆',enabled:false,ipAddress:'',port:19204,navigationPort:19206})">新增车辆连接</button></fieldset>
<h3>后台连接观察</h3><pre>{{data.plcConnections}}</pre><h3>最近保存审计</h3><p v-for="(a,i) in data.audits" :key="i">{{a.at}} · {{a.operator}} · {{a.summary}}</p></template></section></template>
<style scoped>.communication-page{max-width:1500px;margin:auto}.communication-page p{line-height:1.8}.communication-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}.communication-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:16px 0}.communication-grid label{display:grid;gap:7px;font-size:13px}.communication-grid input{min-width:0;width:100%}.communication-page fieldset{border:1px solid #304764;padding:20px;margin:24px 0;min-width:0}.communication-page article{border-bottom:1px solid #304764;padding:20px 0}.communication-page pre{white-space:pre-wrap;overflow-wrap:anywhere}.communication-page a{color:#84d7e9}</style>
